const templates=[{name:'我的快乐校园',tag:'校园生活',bg:'#fffdf7',color:'#3659a1',fill:'#f0f5ff',assets:[64,80,73,117,100,15],headings:['校园里的新发现','我的快乐时光','小小心愿树'],text:['今天，我在校园里发现……\n\n把你的观察写在这里。','最开心的一件事：\n\n和小伙伴一起……','我的心愿是……\n\n我准备这样做……']},{name:'书香伴我成长',tag:'阅读分享',bg:'#fff9ec',color:'#8a5739',fill:'#fff2d8',assets:[72,73,76,65,124,16],headings:['我的好书推荐','摘抄一句好句子','阅读小感悟'],text:['书名：\n作者：\n推荐理由：','这句话让我想到……','读完这本书，我学会了……']},{name:'地球的小小守护者',tag:'绿色环保',bg:'#fbfff6',color:'#3e7757',fill:'#edf6e6',assets:[13,120,123,24,17,40],headings:['地球需要我们的关爱','我的环保行动','绿色小约定'],text:['我发现的环境问题：','节约一滴水，少用一张纸。\n今天我做到了……','和家人一起约定：']},{name:'我的科学小宇宙',tag:'科学探索',bg:'#f6fbff',color:'#36589e',fill:'#eaf2fd',assets:[10,9,78,79,7,11],headings:['奇妙的科学问题','做一个小实验','我的新发现'],text:['我想研究的问题是……','材料：\n步骤：\n观察：','实验中，我发现……']},{name:'安全伴我成长',tag:'安全教育',bg:'#fff9f6',color:'#aa594b',fill:'#fff0e8',assets:[124,126,88,125,127,79],headings:['生活中的安全提醒','遇到危险这样做','我的安全小口诀'],text:['写下你学到的安全知识：','第一步：\n第二步：\n第三步：','把正确的行动编成口诀：']},{name:'秋天的诗与远方',tag:'季节节日',bg:'#fff9ee',color:'#a86839',fill:'#fff0d8',assets:[23,107,1,59,18,31],headings:['秋天的颜色','我喜欢的一首诗','我的秋日故事'],text:['走进秋天，我看到了……','诗题：\n作者：\n诗句：','这个秋天，我想……']}];
let state={version:1,name:'我的快乐校园',paper:'A4',orientation:'landscape',custom:[297,210],bg:'#fffdf7',writingLines:false,nodes:[]};
let selected=null,mode='select',category='全部',grid=false,zoom=0,scale=1,pH=707,pW=1000,history=[],historyIndex=-1,connectFrom=null,drag=null,images=new Map(),ready=false,pendingAction=null,saveTimer,toastTimer;
const uid=()=>crypto.randomUUID?crypto.randomUUID():`n${Date.now()}${Math.random().toString(36).slice(2)}`;
function toast(msg){$('toast').textContent=msg;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3200)}
function mmSize(){if(state.paper==='custom')return state.custom;const a=PAPER[state.paper];return state.orientation==='landscape'?[a[1],a[0]]:a}
function paperLabel(){const [w,h]=mmSize();return `${state.paper==='custom'?'自定义':state.paper==='JISB5'?'B5 (JIS)':state.paper==='B5'?'B5 (ISO)':state.paper} ${w>=h?'横版':'竖版'} · ${w} × ${h} mm`}
function current(){return state.nodes.find(n=>n.id===selected)}
function base(type,x,y,w,h,extra={}){return {id:uid(),type,x,y,w,h,rotation:0,opacity:1,flip:false,locked:false,...extra}}
function add(n){state.nodes.push(n);selected=n.id;setMode('select');commit();syncInspector();return n}
function addSticker(id){const a=ASSETS.find(a=>a.id===id);if(!a)return;return add(base('sticker',pW*.42,pH*.42,145,145,{asset:id,name:a.name}))}
function addText(title=false){return add(base('text',pW*.2,pH*.3,title?600:340,title?95:190,{name:title?'主题标题':'文字',text:title?'写下我的主题':'把你的故事写在这里……',fontSize:title?56:25,font:'hand',color:'#3659a1',bold:title,align:title?'center':'left'}))}
function addFrame(key){return add(base('frame',pW*.25,pH*.3,360,230,{name:frames.find(f=>f[0]===key)[1],style:key,color:'#5879b8',fill:'#f1f6ff',lineWidth:3}))}
function createTemplate(index,initial=false){const t=templates[index];state.name=t.name;state.bg=t.bg;state.nodes=[];state.writingLines=false;const h=pH;state.nodes.push(base('frame',28,28,944,h-56,{name:'页面手绘边框',style:'double',color:t.color,fill:'none',lineWidth:2,locked:true}));state.nodes.push(base('text',140,h*.115,720,h*.14,{name:'主题标题',text:t.name,fontSize:50,font:'hand',bold:true,align:'center',color:t.color}));const layouts=[[75,h*.35,400,h*.265],[75,h*.65,400,h*.23],[515,h*.35,410,h*.53]];layouts.forEach((a,i)=>{state.nodes.push(base('frame',...a,{name:t.headings[i]+'内容框',style:i===2?'lined':'rough',color:t.color,fill:t.fill,lineWidth:2.5}));state.nodes.push(base('text',a[0]+22,a[1]+18,a[2]-44,42,{name:t.headings[i],text:t.headings[i],fontSize:26,font:'hand',color:t.color,bold:true}));state.nodes.push(base('text',a[0]+23,a[1]+66,a[2]-46,a[3]-79,{name:'填写内容',text:t.text[i],fontSize:19,font:'hand',color:'#5e677b',bold:false}));});const spots=[[24,h*.05,155],[817,h*.05,148],[10,h*.8,78],[825,h*.68,116],[428,h*.48,99],[770,h*.29,87]];spots.forEach((a,i)=>state.nodes.push(base('sticker',a[0],a[1],a[2],a[2],{asset:t.assets[i],name:ASSETS[t.assets[i]].name,rotation:i%2?8:-6})));selected=null;$('docName').value=state.name;$('writingLines').checked=false;if(!initial)commit();syncAll()}
function serialize(){return JSON.stringify(state)}
function commit(){const s=serialize();if(history[historyIndex]!==s){history=history.slice(0,historyIndex+1);history.push(s);if(history.length>60)history.shift();historyIndex=history.length-1}updateHistory();saveLocal();render();renderLayers()}
function saveLocal(){clearTimeout(saveTimer);$('saveStatus').textContent='正在保存…';saveTimer=setTimeout(()=>{try{localStorage.setItem('doodle-paper-v1',serialize());$('saveStatus').textContent='已保存到本机'}catch{$('saveStatus').textContent='请保存作品文件';toast('本机存储已满，请点击「保存作品」备份')}},250)}
function updateHistory(){$('undoBtn').disabled=historyIndex<=0;$('redoBtn').disabled=historyIndex>=history.length-1}
function undo(delta){const next=historyIndex+delta;if(next<0||next>=history.length)return;historyIndex=next;state=JSON.parse(history[next]);selected=null;syncAll();saveLocal();updateHistory();toast(delta<0?'已撤销':'已重做')}
function syncAll(){$('docName').value=state.name;$('paperSize').value=state.paper;$('customSize').hidden=state.paper!=='custom';$('customW').value=state.custom[0];$('customH').value=state.custom[1];$('writingLines').checked=state.writingLines;document.querySelectorAll('[data-orientation]').forEach(b=>b.classList.toggle('active',b.dataset.orientation===state.orientation));resize();syncInspector();renderLayers()}
function resize(){const [w,h]=mmSize();pH=1000*h/w;const a=$('canvasArea'),aw=Math.max(230,a.clientWidth-60),ah=Math.max(220,a.clientHeight-60);scale=zoom||Math.min(aw/pW,ah/pH);const dpr=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.round(pW*scale*dpr);canvas.height=Math.round(pH*scale*dpr);canvas.style.width=`${pW*scale}px`;canvas.style.height=`${pH*scale}px`;$('paperWrap').style.width=`${pW*scale}px`;$('paperWrap').style.height=`${pH*scale}px`;a.style.alignItems=zoom&&pH*scale>ah?'flex-start':'center';a.style.justifyContent=zoom&&pW*scale>aw?'flex-start':'center';$('zoomLabel').textContent=zoom?`${Math.round(scale*100)}%`:'适应窗口';$('paperInfo').textContent=paperLabel();render()}
function changePaper(paper,orientation=state.orientation,custom=state.custom){const oldH=pH;state.paper=paper;state.orientation=orientation;state.custom=custom;if(paper==='custom'&&(custom[0]>=custom[1])!==(orientation==='landscape'))state.custom=[custom[1],custom[0]];const [w,h]=mmSize(),newH=1000*h/w,ratio=newH/oldH,factor=Math.sqrt(ratio);for(const n of state.nodes){if(n.type==='connection')continue;if(n.type==='sticker'||n.type==='image'){const cx=n.x+n.w/2,cy=n.y+n.h/2;n.w*=factor;n.h*=factor;n.x=cx-n.w/2;n.y=cy*ratio-n.h/2}else{n.y*=ratio;n.h*=ratio;if(n.type==='text')n.fontSize*=factor}}zoom=0;syncAll();commit()}
function roughRect(c,w,h,color,width=2,style='rough'){c.strokeStyle=color;c.lineWidth=width;c.lineCap='round';c.lineJoin='round';if(style==='dashed')c.setLineDash([9,7]);c.beginPath();const edge=[[0,0],[w,0],[w,h],[0,h],[0,0]];edge.forEach((point,k)=>{if(!k){c.moveTo(1,1);return}const prev=edge[k-1];for(let i=1;i<=15;i++){const t=i/15,dx=point[0]-prev[0],dy=point[1]-prev[1],jitter=Math.sin(i*2.3+k*3)*1.25;c.lineTo(prev[0]+dx*t+(dy?jitter:0),prev[1]+dy*t+(dx?jitter:0))}});c.stroke();c.setLineDash([])}
function drawFrame(c,n){const {w,h,style,color,fill}=n;c.strokeStyle=color;c.lineWidth=n.lineWidth||3;c.fillStyle=fill==='none'?'transparent':fill;if(['round','tape','plain','lined'].includes(style)){c.beginPath();c.roundRect(0,0,w,h,style==='plain'?2:12);c.fill();if(style!=='plain')c.stroke();if(style==='tape'){c.save();c.globalAlpha*=.6;c.fillStyle='#ffda77';c.translate(w/2-40,-7);c.rotate(-.08);c.fillRect(0,0,80,23);c.restore()}if(style==='lined'){c.save();c.globalAlpha*=.2;for(let y=75;y<h-15;y+=30){c.beginPath();c.moveTo(16,y);c.lineTo(w-16,y);c.stroke()}c.restore()}return}if(style==='oval'){c.beginPath();c.ellipse(w/2,h/2,w/2-2,h/2-2,0,0,Math.PI*2);c.fill();c.stroke();return}if(style==='diamond'){c.beginPath();c.moveTo(w/2,0);c.lineTo(w,h/2);c.lineTo(w/2,h);c.lineTo(0,h/2);c.closePath();c.fill();c.stroke();return}c.fillRect(0,0,w,h);if(style==='corner'||style==='bracket'){const l=Math.min(w,h)*.19;c.beginPath();if(style==='corner'){[[0,0],[w,0],[0,h],[w,h]].forEach(([x,y])=>{const dx=x?-1:1,dy=y?-1:1;c.moveTo(x,y+dy*l);c.lineTo(x,y);c.lineTo(x+dx*l,y)})}else{c.moveTo(l,0);c.lineTo(0,0);c.lineTo(0,h);c.lineTo(l,h);c.moveTo(w-l,0);c.lineTo(w,0);c.lineTo(w,h);c.lineTo(w-l,h)}c.stroke();return}if(style==='scallop'){c.beginPath();for(let x=0;x<=w;x+=3){const y=Math.sin(x/9)*3;x?c.lineTo(x,y):c.moveTo(x,y)}for(let y=0;y<=h;y+=3)c.lineTo(w+Math.sin(y/9)*3,y);for(let x=w;x>=0;x-=3)c.lineTo(x,h+Math.sin(x/9)*3);for(let y=h;y>=0;y-=3)c.lineTo(Math.sin(y/9)*3,y);c.closePath();c.stroke();return}roughRect(c,w,h,color,n.lineWidth,style);if(style==='double'){c.save();c.translate(6,6);roughRect(c,w-12,h-12,color,1.2);c.restore()}}
function wrapText(c,text,maxWidth){const lines=[];for(const para of text.split('\n')){if(!para){lines.push('');continue}let line='';for(const ch of para){if(c.measureText(line+ch).width>maxWidth&&line){lines.push(line);line=ch}else line+=ch}lines.push(line)}return lines}
function drawNode(c,n,outline=false){if(n.type==='connection'){drawConnection(c,n);return}c.save();c.globalAlpha=n.opacity;c.translate(n.x+n.w/2,n.y+n.h/2);c.rotate((n.rotation||0)*Math.PI/180);if(n.flip)c.scale(-1,1);c.translate(-n.w/2,-n.h/2);if(n.type==='sticker'||n.type==='image'){const img=images.get(n.type==='sticker'?n.asset:n.src);if(img){if(outline)c.filter='grayscale(1) contrast(1.3) brightness(1.1)';const ratio=img.width/img.height;let w=n.w,h=n.h;if(w/h>ratio)w=h*ratio;else h=w/ratio;c.drawImage(img,(n.w-w)/2,(n.h-h)/2,w,h);c.filter='none'}}else if(n.type==='frame')drawFrame(c,n);else if(n.type==='text'){c.save();c.beginPath();c.rect(0,0,n.w,n.h);c.clip();c.fillStyle=n.color;c.font=`${n.bold?'700':'400'} ${n.fontSize}px ${FONT[n.font]||FONT.hand}`;c.textBaseline='top';c.textAlign=n.align||'left';wrapText(c,n.text,n.w-4).forEach((line,i)=>c.fillText(line,n.align==='center'?n.w/2:2,i*n.fontSize*1.45));c.restore()}else if(n.type==='stroke'){c.strokeStyle=n.color;c.lineWidth=n.lineWidth;c.lineCap='round';c.lineJoin='round';c.beginPath();n.points.forEach(([x,y],i)=>i?c.lineTo(x*n.w,y*n.h):c.moveTo(x*n.w,y*n.h));if(n.points.length===1)c.lineTo(n.points[0][0]*n.w+.2,n.points[0][1]*n.h+.2);c.stroke()}c.restore()}
function centerOf(n){return [n.x+n.w/2,n.y+n.h/2]}
function boundaryPoint(n,toward){const [cx,cy]=centerOf(n),a=(n.rotation||0)*Math.PI/180,dx=toward[0]-cx,dy=toward[1]-cy,lx=Math.cos(a)*dx+Math.sin(a)*dy,ly=-Math.sin(a)*dx+Math.cos(a)*dy,t=Math.min(n.w/2/Math.max(Math.abs(lx),.001),n.h/2/Math.max(Math.abs(ly),.001));return [cx+dx*t,cy+dy*t]}
function connectionPoints(n){const a=state.nodes.find(v=>v.id===n.from),b=state.nodes.find(v=>v.id===n.to);if(!a||!b)return null;return [boundaryPoint(a,centerOf(b)),boundaryPoint(b,centerOf(a))]}
function connectionPath(n){const ends=connectionPoints(n);if(!ends)return null;const [[x,y],[xx,yy]]=ends,dx=xx-x,dy=yy-y,len=Math.hypot(dx,dy),nx=-dy/(len||1),ny=dx/(len||1),path=new Path2D();path.moveTo(x,y);if(n.style==='curve')path.bezierCurveTo(x+dx*.25+nx*45,y+dy*.25+ny*45,x+dx*.75+nx*45,y+dy*.75+ny*45,xx,yy);else if(n.style==='wavy'){for(let i=1;i<=60;i++){const t=i/60,off=Math.sin(t*len/12)*6*Math.sin(t*Math.PI);path.lineTo(x+dx*t+nx*off,y+dy*t+ny*off)}}else{for(let i=1;i<=30;i++){const t=i/30,off=Math.sin(i*2.2)*1.1*Math.sin(t*Math.PI);path.lineTo(x+dx*t+nx*off,y+dy*t+ny*off)}}return {path,ends,nx,ny}}
function drawConnection(c,n){const info=connectionPath(n);if(!info)return;c.save();c.globalAlpha=n.opacity;c.strokeStyle=n.color;c.lineWidth=n.lineWidth||3;c.lineCap='round';if(n.style==='dashed')c.setLineDash([9,8]);c.stroke(info.path);if(n.style==='double'){c.translate(info.nx*6,info.ny*6);c.stroke(info.path)}if(n.style==='arrow'){const [[x,y],[xx,yy]]=info.ends,angle=Math.atan2(yy-y,xx-x);c.beginPath();c.moveTo(xx-15*Math.cos(angle-.45),yy-15*Math.sin(angle-.45));c.lineTo(xx,yy);c.lineTo(xx-15*Math.cos(angle+.45),yy-15*Math.sin(angle+.45));c.stroke()}c.restore()}
function scene(c,width,height,{edit=false,outline=false}={}){c.save();c.setTransform(width/pW,0,0,height/pH,0,0);c.clearRect(0,0,pW,pH);c.fillStyle=state.bg;c.fillRect(0,0,pW,pH);if(state.writingLines){c.strokeStyle='#b5c2d3';c.globalAlpha=.38;c.lineWidth=1;for(let y=90;y<pH-30;y+=28){c.beginPath();c.moveTo(30,y);c.lineTo(pW-30,y);c.stroke()}c.globalAlpha=1}if(edit&&grid){c.strokeStyle='#7996bc';c.globalAlpha=.2;c.lineWidth=.7;for(let x=0;x<pW;x+=25){c.beginPath();c.moveTo(x,0);c.lineTo(x,pH);c.stroke()}for(let y=0;y<pH;y+=25){c.beginPath();c.moveTo(0,y);c.lineTo(pW,y);c.stroke()}c.globalAlpha=1}state.nodes.forEach(n=>drawNode(c,n,outline));if(edit){const n=current();if(n)drawSelection(c,n);if(connectFrom){const from=state.nodes.find(n=>n.id===connectFrom);if(from){c.save();c.strokeStyle='#e0a725';c.lineWidth=4;c.strokeRect(from.x-5,from.y-5,from.w+10,from.h+10);c.restore()}}}c.restore()}
function render(){scene(ctx,canvas.width,canvas.height,{edit:true})}
function drawSelection(c,n){c.save();c.strokeStyle=n.locked?'#a1acbe':'#375be2';c.lineWidth=1.5/scale;c.setLineDash([5/scale,3/scale]);if(n.type==='connection'){const info=connectionPath(n);if(info){c.lineWidth=8;c.globalAlpha=.22;c.stroke(info.path)}c.restore();return}c.translate(n.x+n.w/2,n.y+n.h/2);c.rotate((n.rotation||0)*Math.PI/180);c.strokeRect(-n.w/2,-n.h/2,n.w,n.h);c.setLineDash([]);if(!n.locked){c.fillStyle='#fff';c.lineWidth=2/scale;[[-n.w/2,-n.h/2],[n.w/2,-n.h/2],[-n.w/2,n.h/2],[n.w/2,n.h/2]].forEach(([x,y])=>{c.beginPath();c.arc(x,y,4/scale,0,Math.PI*2);c.fill();c.stroke()});c.beginPath();c.arc(n.w/2,n.h/2,6/scale,0,Math.PI*2);c.fillStyle='#375be2';c.fill();c.stroke()}c.restore()}
function localPoint(n,p){const a=-(n.rotation||0)*Math.PI/180,dx=p.x-n.x-n.w/2,dy=p.y-n.y-n.h/2;return {x:dx*Math.cos(a)-dy*Math.sin(a)+n.w/2,y:dx*Math.sin(a)+dy*Math.cos(a)+n.h/2}}
function hit(p,{skipFrames=false}={}){for(let i=state.nodes.length-1;i>=0;i--){const n=state.nodes[i];if(n.type==='connection'){if(skipFrames)continue;const info=connectionPath(n);if(info){ctx.save();ctx.setTransform(1,0,0,1,0,0);ctx.lineWidth=16/scale;const inside=ctx.isPointInStroke(info.path,p.x,p.y);ctx.restore();if(inside)return n}}else{if(skipFrames&&n.locked)continue;const q=localPoint(n,p);if(q.x>=0&&q.x<=n.w&&q.y>=0&&q.y<=n.h)return n}}return null}
function pointer(e){const r=canvas.getBoundingClientRect();return {x:(e.clientX-r.left)/r.width*pW,y:(e.clientY-r.top)/r.height*pH}}
function setMode(next){mode=next;connectFrom=null;document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===next));$('modeHint').textContent=next==='connect'?'依次点击两个图案，画一条连接线':next==='draw'?'在纸上拖动画笔，记录你的灵感':'点选图案或文字，拖动调整位置';canvas.style.cursor=next==='select'?'default':'crosshair';render()}
canvas.addEventListener('pointerdown',e=>{e.preventDefault();canvas.focus();const p=pointer(e);if(mode==='connect'){const n=hit(p,{skipFrames:true});if(!n||n.type==='stroke'){toast('请点击一个图案、文字或内容框');return}if(!connectFrom){connectFrom=n.id;$('modeHint').textContent='再点击另一个图案，完成连接';render()}else if(connectFrom!==n.id){const from=connectFrom;connectFrom=null;add(base('connection',0,0,0,0,{name:'手绘连接线',from,to:n.id,style:$('lineStyle').value,color:$('penColor').value,lineWidth:Number($('penWidth').value)}));setMode('connect');toast('连接完成，移动图案时连线会跟随')}return}canvas.setPointerCapture(e.pointerId);if(mode==='draw'){drag={kind:'draw',points:[p],color:$('penColor').value,width:Number($('penWidth').value)};return}let n=current();if(n&&n.type!=='connection'&&!n.locked){const q=localPoint(n,p);if(Math.hypot(q.x-n.w,q.y-n.h)<14/scale){drag={kind:'resize',id:n.id,start:p,original:{...n}};return}}n=hit(p);selected=n?n.id:null;syncInspector();renderLayers();render();if(n&&n.type!=='connection'&&!n.locked)drag={kind:'move',id:n.id,start:p,original:{...n}}});
canvas.addEventListener('pointermove',e=>{if(!drag)return;const p=pointer(e);if(drag.kind==='draw'){drag.points.push(p);render();ctx.save();ctx.setTransform(canvas.width/pW,0,0,canvas.height/pH,0,0);ctx.strokeStyle=drag.color;ctx.lineWidth=drag.width;ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();drag.points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.stroke();ctx.restore();return}const n=state.nodes.find(n=>n.id===drag.id);if(!n)return;const o=drag.original;if(drag.kind==='move'){let x=o.x+p.x-drag.start.x,y=o.y+p.y-drag.start.y;if(grid){x=Math.round(x/10)*10;y=Math.round(y/10)*10}n.x=Math.max(-n.w*.8,Math.min(pW-n.w*.2,x));n.y=Math.max(-n.h*.8,Math.min(pH-n.h*.2,y))}else{const a=(o.rotation||0)*Math.PI/180,dx=p.x-drag.start.x,dy=p.y-drag.start.y;let w=Math.max(15,o.w+dx*Math.cos(a)+dy*Math.sin(a)),h=Math.max(15,o.h-dx*Math.sin(a)+dy*Math.cos(a));if($('aspectLock').checked){const factor=Math.max(w/o.w,h/o.h);w=o.w*factor;h=o.h*factor}const dw=w-o.w,dh=h-o.h;n.x=o.x+(dw*Math.cos(a)-dh*Math.sin(a)-dw)/2;n.y=o.y+(dw*Math.sin(a)+dh*Math.cos(a)-dh)/2;n.w=w;n.h=h;if(n.type==='text')n.fontSize=Math.max(8,o.fontSize*w/o.w)}syncPosition();render()});
function endDrag(e){if(!drag)return;if(drag.kind==='draw'){const ps=drag.points,x=Math.min(...ps.map(p=>p.x)),y=Math.min(...ps.map(p=>p.y)),w=Math.max(1,Math.max(...ps.map(p=>p.x))-x),h=Math.max(1,Math.max(...ps.map(p=>p.y))-y);const n=base('stroke',x,y,w,h,{name:'我的手绘线条',color:drag.color,lineWidth:drag.width,points:ps.map(p=>[(p.x-x)/w,(p.y-y)/h])});state.nodes.push(n);selected=n.id}drag=null;if(e&&canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId);commit();syncInspector()}
canvas.addEventListener('pointerup',endDrag);canvas.addEventListener('pointercancel',endDrag);canvas.addEventListener('dblclick',e=>{const n=hit(pointer(e));if(n?.type==='text'){selected=n.id;syncInspector();$('textContent').focus();$('textContent').select()}});
function syncPosition(){const n=current();if(!n||n.type==='connection')return;[['nodeX','x'],['nodeY','y'],['nodeW','w'],['nodeH','h']].forEach(([id,k])=>$(id).value=Math.round(n[k]));$('rotation').value=n.rotation||0;$('rotationVal').textContent=`${Math.round(n.rotation||0)}°`;$('opacity').value=Math.round(n.opacity*100);$('opacityVal').textContent=`${Math.round(n.opacity*100)}%`}
function syncInspector(){const n=current();$('selectionEmpty').hidden=!!n;$('selectionForm').hidden=!n;if(!n)return;$('selectedName').textContent=n.name;$('selectedType').textContent={sticker:'手绘素材',text:'文字',frame:'内容框',image:'自己的图片',stroke:'自由画笔',connection:'手绘连接'}[n.type];$('textControls').hidden=n.type!=='text';$('frameControls').hidden=n.type!=='frame';$('connectionControls').hidden=n.type!=='connection';$('geometryControls').hidden=n.type==='connection';$('duplicateBtn').disabled=n.type==='connection';$('lockBtn').disabled=n.type==='connection';$('lockBtn').textContent=n.locked?'解锁位置':'锁定位置';$('centerBtn').disabled=n.locked;$('rotation').disabled=n.locked;syncPosition();if(n.type==='text'){$('textContent').value=n.text;$('fontSize').value=Math.round(n.fontSize);$('textColor').value=n.color;$('fontFamily').value=n.font;$('boldBtn').classList.toggle('primary',n.bold);$('alignTextBtn').classList.toggle('primary',n.align==='center')}if(n.type==='frame'){$('frameColor').value=n.color;$('frameFill').value=n.fill==='none'?'#ffffff':n.fill;$('noFill').checked=n.fill==='none'}if(n.type==='connection'){$('connectionStyle').value=n.style;$('connectionColor').value=n.color;$('connectionWidth').value=n.lineWidth}}
function patch(key,value){const n=current();if(!n)return;n[key]=value;commit();syncInspector()}
function renderLayers(){const container=$('layersList');container.replaceChildren();[...state.nodes].reverse().forEach(n=>{const item=document.createElement('div');item.className='layer-item'+(n.id===selected?' active':'');const label=document.createElement('span');label.textContent=n.name;const lock=document.createElement('small');lock.textContent=n.locked?'锁定':'';item.append(label,lock);const up=document.createElement('button');up.textContent='↑';up.title='上移一层';up.setAttribute('aria-label',n.name+'上移一层');up.onclick=e=>{e.stopPropagation();selected=n.id;reorder(1)};item.append(up);item.tabIndex=0;item.onclick=()=>{selected=n.id;syncInspector();renderLayers();render()};item.onkeydown=e=>{if(e.key==='Enter')item.click()};container.append(item)})}
function reorder(where){const i=state.nodes.findIndex(n=>n.id===selected);if(i<0)return;const n=state.nodes.splice(i,1)[0],to=where==='top'?state.nodes.length:where==='bottom'?0:Math.max(0,Math.min(state.nodes.length,i+where));state.nodes.splice(to,0,n);commit()}
function remove(){if(!current())return;state.nodes=state.nodes.filter(v=>v.id!==selected&&!(v.type==='connection'&&(v.from===selected||v.to===selected)));selected=null;commit();syncInspector()}
function duplicate(){const n=current();if(!n||n.type==='connection')return;const copy=JSON.parse(JSON.stringify(n));copy.id=uid();copy.x+=22;copy.y+=22;copy.locked=false;copy.name=n.name+' 副本';add(copy)}
function showAssets(){const query=$('search').value.trim(),filtered=ASSETS.filter(a=>(category==='全部'||a.category===category)&&(!query||a.name.includes(query)||a.category.includes(query)));$('categoryTitle').textContent=category==='全部'?'全部手绘':category;$('resultCount').textContent=`${filtered.length} 个`;$('assetGrid').replaceChildren();if(!filtered.length){const p=document.createElement('p');p.className='no-results';p.textContent='换个关键词试试看';$('assetGrid').append(p)}filtered.forEach(a=>{const b=document.createElement('button');b.className='asset-card';b.title=`添加${a.name}`;b.setAttribute('aria-label',`添加${a.name}`);const thumb=document.createElement('canvas');thumb.width=120;thumb.height=120;const img=images.get(a.id);if(img)thumb.getContext('2d').drawImage(img,4,4,112,112);const text=document.createElement('span');text.textContent=a.name;b.append(thumb,text);b.onclick=()=>addSticker(a.id);$('assetGrid').append(b)})}
function buildLibrary(){['全部',...new Set(rowCats)].forEach(cat=>{const b=document.createElement('button');b.textContent=cat;b.classList.toggle('active',cat==='全部');b.onclick=()=>{category=cat;[...$('categories').children].forEach(c=>c.classList.toggle('active',c===b));showAssets()};$('categories').append(b)});frames.forEach(([key,name])=>{const b=document.createElement('button');b.className='frame-card';const p=document.createElement('div');p.className='frame-preview';if(key==='round'||key==='oval')p.style.borderRadius=key==='oval'?'50%':'12px';if(key==='dashed')p.style.borderStyle='dashed';if(key==='double')p.style.borderStyle='double';if(key==='diamond'){p.style.width='40px';p.style.margin='0 auto 8px';p.style.transform='rotate(45deg)'}b.append(p,document.createTextNode(name));b.onclick=()=>addFrame(key);$('frameGrid').append(b)});['#fffdf7','#ffffff','#fff9ec','#f6fbff','#fbfff6','#fff4f5'].forEach(color=>{const b=document.createElement('button');b.style.background=color;b.setAttribute('aria-label','纸张底色 '+color);b.onclick=()=>{state.bg=color;commit()};$('backgrounds').append(b)});templates.forEach((t,i)=>{const b=document.createElement('button');b.className='template-card';const p=document.createElement('div');p.className='template-preview';p.style.background=t.bg;p.style.color=t.color;const title=document.createElement('strong');title.textContent=t.name;const boxes=document.createElement('div');for(let j=0;j<3;j++)boxes.append(document.createElement('i'));p.append(title,boxes);const label=document.createElement('span');label.append(document.createTextNode(t.tag));const small=document.createElement('small');small.textContent='使用模板';label.append(small);b.append(p,label);b.onclick=()=>replaceAction(()=>createTemplate(i));$('templateList').append(b)})}
function replaceAction(action){if(state.nodes.length){pendingAction=action;$('confirmDialog').showModal()}else action()}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}
function filename(){return (state.name||'我的手绘报').replace(/[\\/:*?"<>|]/g,'_').slice(0,80)}
function saveProject(){download(new Blob([serialize()],{type:'application/json'}),filename()+'.doodle.json');toast('可编辑作品已保存，下次在主题模板中打开')}
function validState(s){if(!s||s.version!==1||!Array.isArray(s.nodes)||s.nodes.length>1500||typeof s.name!=='string'||!(s.paper in PAPER||s.paper==='custom')||!['landscape','portrait'].includes(s.orientation)||!/^#[\da-f]{6}$/i.test(s.bg)||!Array.isArray(s.custom)||s.custom.length!==2||s.custom.some(v=>!Number.isFinite(v)||v<50||v>1000))return false;const ids=new Set();for(const n of s.nodes){if(!n||typeof n.id!=='string'||ids.has(n.id)||!['sticker','image','text','frame','stroke','connection'].includes(n.type)||![n.x,n.y,n.w,n.h,n.opacity,n.rotation].every(v=>Number.isFinite(v))||n.w<0||n.h<0||n.w>10000||n.h>10000||Math.abs(n.x)>10000||Math.abs(n.y)>10000||n.opacity<0||n.opacity>1||typeof n.name!=='string')return false;ids.add(n.id);if(n.type==='sticker'&&(!Number.isInteger(n.asset)||!ASSETS[n.asset]))return false;if(n.type==='image'&&(!/^data:image\/(png|jpeg|webp);base64,/.test(n.src)||n.src.length>15000000))return false;if(n.type==='text'&&(typeof n.text!=='string'||n.text.length>20000||!Number.isFinite(n.fontSize)||n.fontSize<1||n.fontSize>500||!FONT[n.font]||!/^#[\da-f]{6}$/i.test(n.color)))return false;if(n.type==='frame'&&(!frames.some(f=>f[0]===n.style)||!/^#[\da-f]{6}$/i.test(n.color)||!(n.fill==='none'||/^#[\da-f]{6}$/i.test(n.fill))))return false;if(n.type==='stroke'&&(!Array.isArray(n.points)||n.points.length>50000||n.points.some(p=>!Array.isArray(p)||p.length!==2||p.some(v=>!Number.isFinite(v)))||!/^#[\da-f]{6}$/i.test(n.color)||!Number.isFinite(n.lineWidth)))return false;if(n.type==='connection'&&(!['wavy','dashed','curve','straight','arrow','double'].includes(n.style)||!/^#[\da-f]{6}$/i.test(n.color)||!Number.isFinite(n.lineWidth)))return false}return s.nodes.every(n=>n.type!=='connection'||ids.has(n.from)&&ids.has(n.to)&&n.from!==n.to)}
async function imageFor(src){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(new Error('图片读取失败'));img.src=src})}
async function loadState(s){const loaded=await Promise.all(s.nodes.filter(n=>n.type==='image').map(async n=>[n.src,await imageFor(n.src)]));loaded.forEach(([key,value])=>images.set(key,value));state=s;selected=null;zoom=0;syncAll();commit()}
async function importProject(file){if(!file)return;if(file.size>22000000){toast('作品文件过大，请使用22MB以内的文件');return}try{const s=JSON.parse(await file.text());if(!validState(s))throw Error('invalid');const loaded=await Promise.all(s.nodes.filter(n=>n.type==='image').map(async n=>[n.src,await imageFor(n.src)]));replaceAction(()=>{loaded.forEach(([k,v])=>images.set(k,v));state=s;selected=null;zoom=0;syncAll();commit();toast('作品已打开')})}catch{toast('无法打开：请选择本工具保存的完整作品文件')}}
async function importImage(file){if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)){toast('请使用 PNG、JPG 或 WebP 图片');return}if(file.size>12000000){toast('请导入12MB以内的图片');return}try{const reader=new FileReader(),src=await new Promise((resolve,reject)=>{reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)}),img=await imageFor(src),c=document.createElement('canvas'),ratio=Math.min(1,1600/Math.max(img.width,img.height));c.width=img.width*ratio;c.height=img.height*ratio;c.getContext('2d').drawImage(img,0,0,c.width,c.height);const data=c.toDataURL('image/png'),clean=await imageFor(data);images.set(data,clean);add(base('image',pW*.35,pH*.3,200,200*img.height/img.width,{name:file.name,src:data}));toast('图片已添加，可以拖动、缩放和旋转')}catch{toast('图片读取失败，请换一张图片')}}
function makePdf(jpeg,width,height,mm){const enc=new TextEncoder(),parts=[],offsets=[0];let length=0;const append=data=>{const v=typeof data==='string'?enc.encode(data):data;parts.push(v);length+=v.length};append('%PDF-1.4\n%\xE2\xE3\xCF\xD3\n');const W=mm[0]*72/25.4,H=mm[1]*72/25.4,content=`q\n${W.toFixed(4)} 0 0 ${H.toFixed(4)} 0 0 cm\n/Im0 Do\nQ\n`,objects=['<< /Type /Catalog /Pages 2 0 R >>','<< /Type /Pages /Kids [3 0 R] /Count 1 >>',`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${W.toFixed(4)} ${H.toFixed(4)}] /Resources << /XObject << /Im0 4 0 R >> >> /Contents 5 0 R >>`];objects.forEach((o,i)=>{offsets[i+1]=length;append(`${i+1} 0 obj\n${o}\nendobj\n`)});offsets[4]=length;append(`4 0 obj\n<< /Type /XObject /Subtype /Image /Width ${width} /Height ${height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${jpeg.length} >>\nstream\n`);append(jpeg);append('\nendstream\nendobj\n');offsets[5]=length;append(`5 0 obj\n<< /Length ${enc.encode(content).length} >>\nstream\n${content}endstream\nendobj\n`);const xref=length;append('xref\n0 6\n0000000000 65535 f \n');for(let i=1;i<=5;i++)append(`${String(offsets[i]).padStart(10,'0')} 00000 n \n`);append(`trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`);return new Blob(parts,{type:'application/pdf'})}
async function exportFile(type){if(!ready){toast('素材仍在载入，请稍后再导出');return}const buttons=[$('pngExport'),$('pdfExport')];buttons.forEach(b=>b.disabled=true);toast('正在生成高清作品…');try{await document.fonts.ready;await new Promise(r=>requestAnimationFrame(r));const mm=mmSize(),dpi=Number($('exportDpi').value),w=Math.round(mm[0]/25.4*dpi),h=Math.round(mm[1]/25.4*dpi);if(w*h>55000000)throw Error('size');const c=document.createElement('canvas');c.width=w;c.height=h;scene(c.getContext('2d'),w,h,{outline:$('outlineExport').checked});if(type==='png'){const blob=await new Promise(r=>c.toBlob(r,'image/png'));if(!blob)throw Error('png');download(blob,filename()+'.png')}else{const blob=await new Promise(r=>c.toBlob(r,'image/jpeg',.97));if(!blob)throw Error('jpeg');download(makePdf(new Uint8Array(await blob.arrayBuffer()),w,h,mm),filename()+'.pdf')}$('exportDialog').close();toast(type==='png'?'高清图片已导出':'PDF已导出，打印时请选择「实际大小」')}catch(e){toast(e.message==='size'?'该尺寸过大，请选择150DPI或缩小纸张':'导出失败，请重试或选择较低清晰度')}finally{buttons.forEach(b=>b.disabled=false)}}
